		private void InputUpdate(float deltaTime) {
            if (EvScript.EvDataManager.Instanse.isUpdateDelegate())
                return;
            if (!PlayerWork.isPlayerInputActive)
                return;
            if (SmartPoint.Components.Fader.fadeOutProgress != 0.0f)
                return;
            if (!isEnableInput)
                return;
            if (EvScript.EvDataManager.Instanse.IsRunningEvent())
                return;

            if (NetworkManager.IsShowApplicationErrorDialog())
            {
                PlayerWork.isPlayerInputActive = false;
                OnCloseErrorDialog = () => PlayerWork.isPlayerInputActive = true;
                return;
            }

            if (MsgWindowManager.IsOpen)
            {
                PlayerStop();
                return;
            }

            if (isOnline && Utils.PushB && !miniMap.isLargeMode)
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SetAndSendMyPlayerState(OpcState.OnlineState.NONE);

            if (nowZoneType == NowZoneType.SecretBase)
            {
                if (!isOnline)
                    return;
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SetReserveEmoticon();
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SetMyEmoticon(OpcState.OnlineState.NONE);
                return;
            }

            if (isOnline)
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.RedoEmoticon();

            if (contextMenu == null && Utils.PushB)
            {
                if (miniMap.isLargeMode)
                    miniMap.ToSmaller(digData);
            }
            else if (!miniMap.isLargeMode && Utils.PushRStick)
            {
                if (miniMap.isOverAllMode)
                    ToAroundMapMode();
                else
                    ToAllOverMapMode();
            }

            if (Utils.PushY)
            {
                OpenCustomMenu();
                return;
            }

            if (nowZoneType != NowZoneType.Kakurega)
            {
                if (Utils.PushR)
                {
                    SearchDigPoint();
                    return;
                }
                if (Utils.PushA)
                    CheckWall();
            }
        }
		private void Update() {
            if (DigPoints != null)
            {
                for (int i = 0; i < DigPoints.Count; i++)
                {
                    var digPoint = DigPoints[i];
                    var position = digPoint.cube.transform.position;
                    if (GetGridPosByDigPointPosition(digPoint.cube.transform) != digPoint.gridPos)
                        SetDigPointPosition(digPoint.cube.transform, digPoint.gridPos.x, digPoint.gridPos.y);
                }
            }
            if (OnFinishBusy != null)
                SceneEndCheck();
        }
