		public void OnZoneChange() {
            OnZoneChangeTime = 0.0f;
            if (NetworkManager.IsShowApplicationErrorDialog())
                PlayerStop();
            if (UgResManager.UgEmoticonSet != null)
                UgResManager.UgEmoticonSet.Close(false);

            int stationIndex;
            if (ugNetManager != null)
            {
                stationIndex = SmartPoint.AssetAssistant.SingletonMonoBehaviour<NetworkManager>.Instance.MyStationIndex;
                if (effectiveBasePlayerIndex != -1)
                {
                    var playerData = ugNetManager.ugOnlinePlayerDatas[effectiveBasePlayerIndex];
                    if (playerData.isNull || !playerData.isEnteredSecretBase)
                        EffectiveMyBase();
                }
            }
            else
            {
                if (effectiveBasePlayerIndex != -1)
                    EffectiveMyBase();
                stationIndex = 0;
            }
            d_stationIndex = stationIndex;

            ZoneID zoneID = PlayerWork.zoneID;
            var fossilNum = dataMng.FossilNumData.Find(x => x.ZoneID == zoneID);
            IsBase = ZoneWork.IsSecretBase(zoneID);
            isEnableInput = true;
            miniMap.UpdateLandMarkIcons();
            nowZoneType = NowZoneType.Way;
            bool isLoaded = isLoadedOrVisit && !isFallEnter;
            isLoadedOrVisit = false;
            if (isDebugDraw)
            {
                statueBuff.UpdateStatueParam();
                DebugDrawPokeRate();
            }
            EntryType entryType = CheckEntryType(zoneID, isLoaded);

            if (fossilNum == null)
            {
                nowZoneType = IsBase ? NowZoneType.SecretBase : NowZoneType.Kakurega;
                if (!IsBase && isOnline && ugNetManager.GetMyPlayerState() == OpcState.OnlineState.NOW_BATTLE)
                    ugNetManager.RedoEmoticon();
            }

            if (isLoaded || entryType == EntryType.NotZoneChange || entryType == EntryType.DigReturn)
            {
                if (nowZoneType != NowZoneType.Kakurega && !CheckAroundWalls())
                {
                    Vector3 adjust = GetAdjustPos() * 0.5f;
                    EntityManager.activeFieldPlayer.worldPosition.x -= adjust.x;
                    EntityManager.activeFieldPlayer.worldPosition.z += adjust.z;
                }
                EntityManager.activeFieldPlayer.worldPosition.y = 0.0f;

                if (entryType == EntryType.NotZoneChange || entryType == EntryType.DigReturn)
                {
                    if (entryType == EntryType.DigReturn)
                    {
                        miniMap.UpdateDigPoint(digData);
                        digData.PrevSceneisDigFossil = false;
                        if (MsgWindowManager.IsOpen)
                            MsgWindowManager.CloseMsg();
                    }
                    if (isOnline)
                    {
                        SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.DeleteAllOpcCharacter();
                        SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SendOnFinishDigFossil();
                        SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnZoneChange();
                        SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.RedoEmoticon();
                    }
                    return;
                }
            }

            if (IsBase)
                EvScript.EvDataManager.Instanse.JumpLabel("ev_uga_himitukiti_fast", null);
            DeleteAllDigPoints();
            DeleteNpc();
            DeleteAllSecretBase();
            OnZoneChangeCallBack?.Invoke();
            if (isOnline)
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnZoneChange();
            if (nowZoneType == NowZoneType.SecretBase)
                return;
            statueBuff.UpdateStatueParam();
            statueBuff.UpdateIcons();
            if (nowZoneType == NowZoneType.Kakurega)
            {
                if (isLoaded)
                    LOAD_POKE();
            }
            else
            {
                CreateDigPoints(stationIndex);
                CreateNPC(zoneID);
                OnZoneChangeAfter(zoneID);
            }
        }
		public void CreateDigPoints(int stationIndex) {
            if (stationIndex == -1)
                return;
            int DigGroupID;
            var zoneData = UgResManager.UgDigFossilePosGroups.list.Find(x => x.zoneID == PlayerWork.zoneID);
            DigGroupID = ugDigGroupList.DigFossilIDs[stationIndex];
            d_stationIndex = stationIndex;
            d_digGroupID = DigGroupID;
            UgDigFossilePosGroup fossilPosData = zoneData == null ? null : zoneData.list.Find(x => x.ID == DigGroupID);
            var fossilNum = dataMng.FossilNumData.Find(x => x.ZoneID == PlayerWork.zoneID);
            if (fossilNum == null)
                return;
            int num = UnityEngine.Random.Range(fossilNum.min, fossilNum.max + 1);
            for (int i = 0; i < num; i++)
            {
                var model = CreateDigPointModel(fossilPosData);
                if (model != null)
                {
                    model.StationIndex = stationIndex;
                    DigPoints.Add(model);
                }
            }
            DigPoints.ForEach(model => CreateDigPointGameObject(model));
            if (miniMap == null)
                miniMap = FindObjectOfType<UgMiniMapComponent>();
            miniMap.UpdateDigPoint(digData);
        }
		public void DeleteAllDigPoints() {
            DigPoints.ForEach(x => x.Destroy());
            DigPoints.Clear();
        }
		private void OnZoneChangeAfter(global::ZoneID zoneID) {
            DG.Tweening.DOVirtual.DelayedCall(0.1f, () =>
            {
                EntityManager.BuildFieldEntities();
                if (miniMap == null)
                    miniMap = FindObjectOfType<UgMiniMapComponent>();
                miniMap.UpdateDigPoint(digData);
                UgSecretBase myBase = PlayerWork.ugSaveData.ugRecord.myBase;
                if (IsHaveSecretBase())
                {
                    if (zoneID == (ZoneID)myBase.zoneID)
                    {
                        CreateSecretBase_Immidiate(myBase, myStationIndex);
                    }
                    else
                    {
                        SecretBases.Add(new SecretBaseModel(myBase, false, null, myStationIndex)
                        {
                            gridPos = new Vector2Int(myBase.posX, myBase.posY),
                        });
                    }
                }
                miniMap.UpdateSecretBase(SecretBases);
            }, true);
        }
		private void MyUpdate(float deltaTime) {
            if (KousekiBonusTime > 0.0f)
            {
                KousekiBonusTime -= deltaTime;
                if (!(KousekiBonusTime > 0.0f))
                    KousekiCount = 0;
            }
            if (miniMap != null)
                miniMap.SetVisible(!IsBase && !FieldManager.Instance.IsMenuOpen);
            if (OnZoneChangeTime < 1.0f)
                OnZoneChangeTime += deltaTime;
        }
