		private global::System.Collections.IEnumerator Start() {
            dataMng = new UgFieldDataManager();
            FieldCanvas.UgSetUp(true);
            ugDigGroupList.Init();
            if (!PlayerWork.ugSaveData.ugRecord.myBase.isNull)
            {
                nowBaseModel = PlayerWork.ugSaveData.ugRecord.myBase;
                nowBasePlayerIndex = -1;
                EffectiveBase = PlayerWork.ugSaveData.ugRecord.myBase;
            }
            yield return SmartPoint.AssetAssistant.Sequencer.Start(dataMng.LoadMD());
            yield return SmartPoint.AssetAssistant.Sequencer.Start(dataMng.LoadAsset());
            UgResManager.UgEmoticonSet.OnDeside = OnEmoticonDeside;
