            statueBuff = UgResManager.GetUgCanvas().transform.Find("rect2dmask/UIStatueBuff").GetComponent<StatueBuff>();
            statueBuff.UpdateStatueParam();
            statueBuff.UpdateIcons();
            prevZoneID = (ZoneID)0x161;
