            _isInitAddUpdate = true;
            AddInputUpdate();
            isEnableInput = true;
            isFallEnter = false;
        }
		private void StartSession() {
            if (ugNetManager != null)
                return;
            var connectType = UgNetworkManager.connectType;
            if (connectType == INL1.IlcaNetSessionNetworkType.Lan)
                return;
            var matchingType = UgNetworkManager.matchingType;
            int areaID = GetAreaIDfromZoneID(PlayerWork.zoneID);
            var go = new GameObject("UgNetworkManager");
            var matchingParam = new MatchingParam
            {
                GameModeID = NetworkHelper.CreateUnderGroundGameMode(matchingType, connectType, (ushort)(areaID << 4)),
                SessionMaxPlayerCount = 8,
                netType = connectType,
                startMode = INL1.IlcaNetSessionGamingStartMode.Natural,
                password = UgNetworkManager.password,
            };
            ugNetManager = go.AddComponent<UgNetworkManager>();
            ugNetManager.SetMatchingParam(matchingParam);
        }
		private void OnEmoticonDeside(int index) {
            if (!SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.isInstantiated)
                return;
            var nowState = SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.GetMyPlayerState();
            OpcState.OnlineState state;
            switch (index)
            {
                case 0:
                    state = OpcState.OnlineState.LIKES;
                    break;
                case 1:
                    state = OpcState.OnlineState.CROSS;
                    break;
                case 2:
                    state = OpcState.OnlineState.EXCLAMATION;
                    break;
                case 3:
                    state = OpcState.OnlineState.DIG_FOSILL;
                    break;
                case 4:
                    state = OpcState.OnlineState.TOGETHER;
                    break;
                case 5:
                    state = OpcState.OnlineState.GET;
                    break;
                default:
                    state = OpcState.OnlineState.NONE;
                    break;
            }
            if (state == nowState)
                state = OpcState.OnlineState.NONE;
            SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SetAndSendMyPlayerState(state);
        }
		private void OnDestroy() {
