            if (FieldManager.abUnloader != null)
            {
                FieldManager.abUnloader.Unload(Utils.AssetUnloader.ID_DEMO);
                FieldManager.abUnloader.Unload(Utils.AssetUnloader.ID_UG_COMMON);
            }
