                Destroy(ugNetManager.gameObject);
            ugNetManager = null;
            OnCloseErrorDialog = null;
            OnFinishMsg = null;
            OnFinishBusy = null;
            OnCreateOtherSecretBase = null;
            Instance = null;
        }
