                var addTypeKakurituDic = statueBuff.AddTypeKakurituDic;
                zoneData = GameManager.mapInfo[(int)PlayerWork.zoneID];
                int[] baseRates = new int[18];
                int[] addRates = new int[18];
                (int, int)[] rates = new (int, int)[18];
                EnablePokeTypes = new List<int>();
                if (zoneData.LandmarkType != -1)
                {
                    var randMark = Array.Find(UgResManager.UgRandMark.table, x => x.id == zoneData.LandmarkType);
                    randMark.typerate.CopyTo(baseRates, 0);
                    if (statueBuff.DebugPokeSlots != null)
                    {
                        Array.ForEach(statueBuff.DebugPokeSlots, x =>
                        {
                            if (EnablePokeTypes.Exists(type => (int)x.ts.type == type))
                                return;
                            EnablePokeTypes.Add((int)x.ts.type);
                        });
                    }
                }
                foreach (var kv in addTypeKakurituDic)
                    addRates[kv.Key] = kv.Value;
                if (EnablePokeTypes.Count != 0)
                {
                    for (int i = 0; i < 18; i++)
                    {
                        if (!EnablePokeTypes.Exists(x => i == x))
                        {
                            baseRates[i] = 0;
                            addRates[i] = 0;
                        }
                    }
                }
                int total = 0;
                for (int i = 0; i < 18; i++)
                {
                    rates[i].Item1 = i;
                    rates[i].Item2 = addRates[i] + baseRates[i];
                    total += rates[i].Item2;
                }
                Array.Sort(rates, (a, b) => b.Item2 - a.Item2);
                for (int i = 0; i < 18; i++)
                {
                    float rate = (float)rates[i].Item2 / (float)total;
                    if (rate == 0.0f)
                        continue;
                    int typeID = rates[i].Item1;
                    int slotCount = statueBuff.DebugPokeSlots != null ? Array.FindAll(statueBuff.DebugPokeSlots, x => typeID == (int)x.ts.type).Length : 0;
                    message = message + (Pml.PokeType)typeID + "=> ベース値:" + baseRates[typeID] + " 加算値:" + addRates[typeID] + " 確率:" + Mathf.RoundToInt(rate * 100.0f) + "% " + slotCount + "枠\n";
                }
                statueBuff.DebugPokeSlots = null;
            }
            FieldCanvas.Debug_ShowDisplayMessage(message);
        }
