		private global::Dpr.UnderGround.UgFieldManager.EntryType CheckEntryType(global::ZoneID zoneID, bool isLoaded) {
            EntryType result;
            if (digData.PrevSceneisDigFossil)
                result = EntryType.DigReturn;
            else if (prevZoneID == (ZoneID)0x161)
                result = isLoaded ? EntryType.SaveReturn : EntryType.FirstEnter;
            else
                result = prevZoneID == zoneID ? EntryType.NotZoneChange : EntryType.ZoneChange;
            prevZoneID = zoneID;
            return result;
