		private void CheckWall() {
            ZoneID zoneID;
            Vector2Int grid;
            if (OnZoneChangeTime < 1.0f)
                return;
            if (!PlayerWork.isPlayerInputActive)
                return;
            Vector2Int? wallGridPos = GetWallGridPos();
            if (!wallGridPos.HasValue)
                return;
            grid = wallGridPos.Value;
            zoneID = PlayerWork.zoneID;
            var posData = dataMng.FossilPosDataList.Find(x => x.zoneID == zoneID);
            DIR wallDir = DIR.DIR_NOT;
            if (!posData.CheckWallPos(grid, out wallDir))
                return;
            if (wallDir == DIR.DIR_RIGHT)
                wallDir = posData.CheckRightOrLeft(grid);
            if (CheckSecretBase(grid))
                return;
            if (CheckDigPoint(wallDir))
                return;
            if (ItemWork.GetItemInfo(0x712).count < 1)
                return;
            bool existDigPoint = DigPoints.Exists(x => x.gridPos == grid);
            bool existSecretBase = SecretBases.Exists(x => x.gridPos == grid);
            if (isOnline)
            {
                Vector2Int checkGrid;
                var opcs = ugNetManager.GetTargetStateOpc(OpcState.OnlineState.NOW_DIG_FOSILE);
                if (((int)wallDir & ~1) == 2)
                    checkGrid = grid - Utils.directList[(int)wallDir];
                else
                    checkGrid = grid + Utils.directList[(int)wallDir];
                bool existOpc = opcs.Exists(x => Utils.IsAdjacent(checkGrid, x.GetEntity().gridPosition));
                if (existDigPoint || existSecretBase)
                    return;
                if (existOpc)
                    return;
            }
            else if (existDigPoint || existSecretBase)
            {
                return;
            }
            OpenCreateHoleSelector(wallDir, grid);
        }
