		private global::Dpr.UnderGround.UgFieldManager.DigPointModel CreateDigPointModel(global::UgDigFossilePosGroup fossilPosData) {
            buffPosList.Clear();
            buffPosList.AddRange(fossilPosData.Grids);
            while (true)
            {
                Vector2Int pos;
                if (buffPosList.Count == 0)
                    return null;
                int index = UnityEngine.Random.Range(0, buffPosList.Count);
                pos = buffPosList[index];
                buffPosList.RemoveAt(index);
                bool existDigPoint = DigPoints.Exists(x => x.gridPos == pos);
                bool existSecretBase = SecretBases.Exists(x => x.gridPos == pos);
                if (!existDigPoint && !existSecretBase)
                    return new DigPointModel(pos.x, pos.y, myStationIndex);
            }
        }
		private bool isNear(global::UnityEngine.Vector2Int pos1, global::UnityEngine.Vector2Int pos2) {
            return (pos1.x - 2 <= pos2.x && pos2.x <= pos1.x + 2) || (pos1.y - 2 <= pos2.y && pos2.y <= pos1.y + 2);
        }
		public void SearchDigPoint() {
            if (isSearching)
                return;
            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.S_UND012, null);
            searchSize = 0.0f;
            SmartPoint.AssetAssistant.Sequencer.update += update;
            FieldManager.Instance.CallEffect(EffectFieldID.EF_SU_FUSSIL_TANSA, dummy,
                eff => eff.gameObject.transform.localScale = Vector3.one * 1.6f,
                eff =>
                {
                    isSearching = false;
                    Destroy(dummy.gameObject);
                    SmartPoint.AssetAssistant.Sequencer.update -= update;
                });
            isSearching = true;

            void update(float deltaTime)
            {
                searchSize = Mathf.Clamp(deltaTime * 10.0f + searchSize, 0.0f, 6.0f);
                DigPoints.ForEach(model =>
                {
                    if (Vector3.Distance(model.GetPosition(), EntityManager.activeFieldPlayer.worldPosition) < searchSize)
                        model.KiraKira(0.0f);
                });
                dummy.transform.position = EntityManager.activeFieldPlayer.transform.position;
            }
        }
		public void KiraKira() {
            DigPoints[0].KiraKira(0.0f);
        }
		private bool CheckDigPoint(global::DIR wallDIR) {
            DigPointModel model;
            for (int i = 0; i < DigPoints.Count; i++)
            {
                // shipped: empty loop body (@018b0f70-018b0fa0, counter only)
            }
            model = null;
            foreach (var digPoint in DigPoints)
            {
                if (digPoint.cube.activeSelf & Vector3.Distance(digPoint.cube.transform.position, EntityManager.activeFieldPlayer.transform.position) < 1.6f)
                {
                    model = digPoint;
                    break;
                }
            }
            if (model == null)
                return false;

            PlayerStop();
            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            var msgWindowParam = CreateMsgWindowParam(UG_MSG_FILE, DIG_START_MESSAGE);
            MsgWindowManager.OpenMsg(msgWindowParam);
            IsClosableMessage = true;
            isDigCancel = false;
            if (isOnline)
            {
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnDigEndOtherPlayer = stationIndex =>
                {
                    if (model.StationIndex == stationIndex)
                    {
                        isDigCancel = true;
                        SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnDigEndOtherPlayer = null;
                    }
                };
            }
            msgWindowParam.onFinishedShowAllMessage = () =>
            {
                SmartPoint.AssetAssistant.Sequencer.update += DigCancelCheck;
                MsgWindowManager.OpenYesNoMenu(selectIndex =>
                {
                    if (selectIndex == 0)
                    {
                        if (model.isFriends)
                        {
                            if (isOnline)
                            {
                                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SendOnJoinDigFossil(model.StationIndex, model.gridPos);
                                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.isMainKasekihori = false;
                                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnDigFossilJoinPermission = GotoDigFossil;
                                SetLeaveCheckTarget(model.StationIndex);
                                OnLeaveTargetPlayer = () => GotoDigFossil(false);
                                int myIndex = myStationIndex; // shipped: read and discarded (@018ba3e4-018ba438)
                            }
                        }
                        else
                        {
                            GotoDigFossil(true);
                            if (isOnline)
                            {
                                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.digFossileMainPlayerStationIndex = -1;
                                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.isMainKasekihori = true;
                                CreateTonarihoriGrids(model.gridPos);
                                var tonarihoriList = SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.tonarihoriList;
                                SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SendOnPlayDigFossil(model.gridPos, tonarihoriList[0].Item2, tonarihoriList[1].Item2);
                            }
                        }
                        digData.PrevSceneisDigFossil = true;
                        isEnableInput = false;
                        model.Destroy();
                        DigPoints.Remove(model);
                    }
                    else
                    {
                        PlayerWork.isPlayerInputActive = true;
                        MsgWindowManager.CloseMsg();
                    }
                    IsClosableMessage = false;
                    if (SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.isInstantiated)
                        SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnDigEndOtherPlayer = null;
                    SmartPoint.AssetAssistant.Sequencer.update -= DigCancelCheck;
                }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
            };
            return true;

            void GotoDigFossil(bool isOK)
            {
                if (isOK)
                {
                    PlayerWork.isDigFossil = true;
                    Vector2Int offset = Vector2Int.zero;
                    PlayerWork.SetPlayerGrid(EntityManager.activeFieldPlayer.gridPosition + offset);
                    PlayerWork.SetPlayerHeight(0.0f);
                    PlayerWork.SetPlayerRotation(EntityManager.activeFieldPlayer.yawAngle);
                }
                else
                {
                    PlayerWork.isPlayerInputActive = true;
                    digData.PrevSceneisDigFossil = false;
                    isEnableInput = true;
                }
                MsgWindowManager.CloseMsg();
                ClearLeaveCheckTarget();
            }
        }
		public void DigCancelCheck(float deltaTime) {
            if (!isDigCancel)
                return;
            PlayerWork.isPlayerInputActive = true;
            MsgWindowManager.CloseMsg();
            SmartPoint.AssetAssistant.SingletonMonoBehaviour<MsgWindowManager>.Instance.CloseContextMenu();
