		private bool CheckSecretBase(global::UnityEngine.Vector2Int grid) {
            SecretBaseModel sbModel = null;
            for (int i = 0; i < SecretBases.Count; i++)
            {
                if (SecretBases[i].IsCollide())
                {
                    sbModel = SecretBases[i];
                    break;
                }
            }
            if (sbModel == null || sbModel.go == null)
                return false;

            PlayerStop();
            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            string label;
            if (sbModel.isFriends)
            {
                label = ENTER_BASE_FRIEND;
                MessageWordSetHelper.SetPlayerNickNameWord(0, SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.ugOnlinePlayerDatas[sbModel.StationIndex].playerNameData);
            }
            else
            {
                label = ENTER_BASE;
            }
            var msgWindowParam = CreateMsgWindowParam(UG_MSG_FILE, label);
            MsgWindowManager.OpenMsg(msgWindowParam);
            IsClosableMessage = true;
            SetLeaveCheckTarget(sbModel.StationIndex);
            OnLeaveTargetPlayer = Cancel;
            msgWindowParam.onFinishedShowAllMessage = () =>
            {
                MsgWindowManager.OpenYesNoMenu(index =>
                {
                    if (index == 0)
                    {
                        if (sbModel.isFriends)
                        {
                            SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SendOnEnterSecretBase(sbModel.StationIndex);
                            SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.OnSecretBaseEnter = OnReceiveSBData;
                        }
                        else
                        {
                            GotoSecretBase(sbModel);
                        }
                    }
                    else
                    {
                        PlayerWork.isPlayerInputActive = true;
                    }
                    IsClosableMessage = false;
                    MsgWindowManager.CloseMsg();
                }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
            };
            return true;

            void Cancel()
            {
                PlayerWork.isPlayerInputActive = true;
                MsgWindowManager.CloseMsg();
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<MsgWindowManager>.Instance.CloseContextMenu();
                IsClosableMessage = false;
            }

            void OnReceiveSBData(NetSecretBaseData netSBData)
            {
                sbModel.data.expansionStatus = netSBData.data.expansionStatus;
                sbModel.data.goodCount = netSBData.data.goodCount;
                sbModel.data.ugStoneStatue = netSBData.data.ugStoneStatue;
                if (isOnline)
                    SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.ugOnlinePlayerDatas[netSBData.FromStationIndex].isEnteredSecretBase = true;
                GotoSecretBase(sbModel);
                ClearLeaveCheckTarget();
            }
        }
		private global::System.Nullable<global::UnityEngine.Vector2Int> GetWallGridPos() {
            var player = EntityManager.activeFieldPlayer;
            Vector3 direction = player.transform.TransformDirection(Vector3.forward);
            Ray ray = new Ray(player.transform.position + direction * 0.2f, direction);
            if (Physics.Raycast(ray, out RaycastHit hit, 0.5f))
            {
                Vector3 position = hit.collider.transform.position;
                return new Vector2Int(-Mathf.RoundToInt(position.x), Mathf.RoundToInt(position.z));
            }
            return null;
        }
