		private void OpenCreateHoleSelector(global::DIR wallDir, global::UnityEngine.Vector2Int grid) {
            PlayerStop();
            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            var msgWindowParam = CreateMsgWindowParam(UG_MSG_FILE, IsHaveSecretBase() ? DRILL_USE_HIKKOSHI : DRILL_USE_MESSAGE);
            MsgWindowManager.OpenMsg(msgWindowParam);
            OnCreateOtherSecretBase = CancelCheck;
            msgWindowParam.onFinishedShowAllMessage = () =>
            {
                MsgWindowManager.OpenYesNoMenu(selectIndex =>
                {
                    bool isExists = isOtherSecBaseExists();
                    if (selectIndex == 0 && !isExists)
                    {
                        UGRecord ugRecord = PlayerWork.UgRecord;
                        ugRecord.myBase.zoneID = (short)PlayerWork.zoneID;
                        ugRecord.myBase.posX = (short)grid.x;
                        ugRecord.myBase.posY = (short)grid.y;
                        ugRecord.myBase.direction = (byte)wallDir;
                        PlayerWork.UgRecord = ugRecord;
                        EvScript.EvDataManager.Instanse.OnOpenMenu();
                        CreateSecretBase(ugRecord.myBase);
                        miniMap.UpdateSecretBase(SecretBases);
                    }
                    PlayerWork.isPlayerInputActive = true;
                    MsgWindowManager.CloseMsg();
                    OnCreateOtherSecretBase = null;
                }, ContextMenuWindow.CursorType.Arrow, true, true, null, AK.EVENTS.UI_COMMON_DECIDE);
            };

            bool isOtherSecBaseExists()
            {
                return SecretBases.Exists(x => x.gridPos == grid);
            }

            void CancelCheck()
            {
                if (!isOtherSecBaseExists())
                    return;
                PlayerWork.isPlayerInputActive = true;
                MsgWindowManager.CloseMsg();
                SmartPoint.AssetAssistant.SingletonMonoBehaviour<MsgWindowManager>.Instance.CloseContextMenu();
                OnCreateOtherSecretBase = null;
            }
        }
		public global::UnityEngine.GameObject HoleInstantiate(global::DIR wallDir, global::UnityEngine.Vector3 pos) {
            var player = EntityManager.activeFieldPlayer; // shipped: read and discarded (indirect flag 0x4b79768 @018b292c, no use)
            GameObject hole = Instantiate(dataMng.GetSecretBaseObject()) as GameObject;
            hole.transform.SetParent(transform, false);
            hole.transform.Find("Mask").GetComponent<MeshRenderer>().material = new Material(SmartPoint.AssetAssistant.AssetManager.FindShader("Custom/StencilMask"));
            switch (wallDir)
            {
                case DIR.DIR_RIGHT:
                    hole.transform.localEulerAngles += Vector3.up * 90.0f;
                    break;
                case DIR.DIR_LEFT:
                    hole.transform.localEulerAngles += Vector3.up * -90.0f;
                    break;
            }
            hole.transform.position = pos;
            return hole;
        }
