		private void YmenuHandler(int selectIndex) {
            switch (selectIndex)
            {
                case 0:
                    UgResManager.UgEmoticonSet.Open();
                    break;
                case 1:
                    if (miniMap.isLargeMode)
                        miniMap.ToSmaller(digData);
                    else
                        miniMap.ToLarger(digData);
                    break;
                case 2:
                    OpenGotoGroundSelector();
                    return;
            }
            PlayerWork.isPlayerInputActive = true;
            contextMenu = null;
            isContextMenuOpend = false;
            EvScript.EvDataManager.Instanse.OnCloseMenu();
            if (selectIndex == 0)
                PlayerWork.isPlayerInputActive = false;
        }
		private void OpenCustomMenu() {
            bool isNetwork;
            if (!PlayerWork.isPlayerInputActive)
                return;
            if (isContextMenuOpend)
                return;
            if (EntityManager.activeFieldPlayer.IsSwim())
                return;
            if (FlagWork.GetSysFlag(EvScript.EvWork.SYSFLAG_INDEX.SYS_INPUT_OFF))
                return;
            if (PlayerWork.transitionZoneID != (ZoneID)(-1))
                return;
            if (IsBusy())
                return;
            EvScript.EvDataManager.Instanse.OnOpenMenu();
            isContextMenuOpend = true;
            PlayerStop();
            var msgFile = SmartPoint.AssetAssistant.SingletonMonoBehaviour<MessageManager>.Instance.GetMsgFile(UG_MSG_FILE);
            isNetwork = ugNetManager != null;
            string[] labels = isNetwork ? Y_MENU_LABEL_ONLINE : Y_MENU_LABEL;
            var param = new ContextMenuWindow.Param();
            param.itemParams = new ContextMenuItem.Param[labels.Length];
            for (int i = 0; i < labels.Length; i++)
            {
                param.itemParams[i] = new ContextMenuItem.Param();
                param.itemParams[i].text = msgFile.GetFormattedMessage(labels[i]);
                param.itemParams[i].messageIndex = i;
            }
#if !SWITCH
            // s40: a 1280x720 screen position -> world pixels with the game's own helper (UIManager.ScreenScaled; identity at 720p)
            var pcPosition = new Vector2(800.0f, 300.0f);
            Dpr.UI.UIManager.ScreenScaledPoint(ref pcPosition);
            param.position = pcPosition;
#else
            param.position = new Vector2(800.0f, 300.0f);
#endif
            param.minItemWidth = 122.0f;
            param.useLoopAndRepeat = false;
            Audio.AudioManager.Instance.PlaySe(AK.EVENTS.UI_COMMON_DECIDE, null);
            contextMenu = UIManager.Instance.CreateUIWindow<ContextMenuWindow>(UIWindowID.CONTEXTMENU);
            contextMenu.onClicked = item =>
            {
                YmenuHandler(item.param.messageIndex + (isNetwork ? 0 : 1));
                return true;
            };
            contextMenu.Open(param);
        }
