		public void GotoSecretBase(global::Dpr.UnderGround.UgFieldManager.SecretBaseModel sbModel) {
            nowBasePlayerIndex = sbModel.StationIndex;
            if (nowBasePlayerIndex != myStationIndex && nowBasePlayerIndex != -1 && isOnline)
            {
                FlagWork.SetSysFlag(EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_UG_HIMITUKITI_INTO, true);
                SetSecretBasePlayerNameData(ugNetManager.ugOnlinePlayerDatas[nowBasePlayerIndex].playerNameData);
            }
            else
            {
                nowBasePlayerIndex = -1;
                sbModel.data = PlayerWork.ugSaveData.ugRecord.myBase;
            }
            nowBaseModel = sbModel.data;
            isEnableInput = false;
            float angle = nowBaseModel.direction == (byte)DIR.DIR_LEFT ? 90.0f : (nowBaseModel.direction == (byte)DIR.DIR_RIGHT ? 270.0f : 180.0f);
            MoveTargetPos(new Vector3(-nowBaseModel.posX, 0.0f, nowBaseModel.posY), angle, () =>
            {
                PlayerWork.SetTransitionZone(GetSecretBaseZone(PlayerWork.zoneID, nowBaseModel.expansionStatus), 0);
                isEnableInput = true;
                Audio.AudioManager.Instance.PlaySe(AK.EVENTS.S_FI001, null);
            });
        }
		private global::ZoneID GetSecretBaseZone(global::ZoneID zone, int expansionStatus) {
            int baseZone;
            if ((int)zone < 0x201)
                baseZone = 0x273;
            else if ((int)zone < 0x206)
                baseZone = 0x276;
            else if ((int)zone < 0x20d)
                baseZone = 0x279;
            else if ((int)zone == 0x20d)
                baseZone = 0x27c;
            else if ((int)zone < 0x213)
                baseZone = 0x27f;
            else if ((int)zone < 0x218)
                baseZone = 0x282;
            else if ((int)zone <= 0x21e)
                baseZone = 0x285;
            else
                baseZone = 0x273;
            return (ZoneID)(baseZone + expansionStatus);
        }
