		private void CreateSecretBase(global::DPData.UgSecretBase secretBase) {
            Vector3 secBasePos;
            ItemWork.SubItem(0x712, 1);
            FlagWork.SetFlag(EvScript.EvWork.FLAG_INDEX.FE_DONE_HIMITUKITI, true);
            FlagWork.SetSysFlag(EvScript.EvWork.SYSFLAG_INDEX.SYS_FLAG_UG_BASE, true);
            isEnableInput = false;
            var player = EntityManager.activeFieldPlayer;
            secBasePos = GetHoleCreatePosition(secretBase);
            if (Vector3.Distance(secBasePos, player.worldPosition) > 0.2f)
            {
                // GetAngle never reads its DIR argument; the shipped call leaves x1 unset (@018b3a58).
                MoveTargetPos(secBasePos, GetAngle(secBasePos, (DIR)secretBase.direction), () => Anahori(secretBase, secBasePos));
            }
            else
            {
                Anahori(secretBase, secBasePos);
            }
        }
		private void Anahori(global::DPData.UgSecretBase secretBase, global::UnityEngine.Vector3 secBasePos) {
            var player = EntityManager.activeFieldPlayer; // shipped: read and discarded (indirect flag 0x4b79768 @018b3f1c, no use)
            MoveTargetPos(secBasePos, GetHoleCreateAngle(secretBase), () =>
            {
                SecretBaseModel model = CreateSecretBase_Immidiate(secretBase, myStationIndex);
                PlayHoleEffect(model.go.transform.position, model.go.transform.rotation);
                model.go.SetActive(false);
                if (isOnline)
                    SmartPoint.AssetAssistant.SingletonMonoBehaviour<UgNetworkManager>.Instance.SendSecretBaseInfo(PlayerWork.zoneID);
                DG.Tweening.DOVirtual.DelayedCall(0.4f, () =>
                {
                    model.go.SetActive(true);
                    miniMap.UpdateSecretBase(SecretBases);
                }, true);
                DG.Tweening.DOVirtual.DelayedCall(1.0f, () =>
                {
                    isEnableInput = true;
                    EvScript.EvDataManager.Instanse.OnCloseMenu();
                }, true);
            });
        }
		private global::UnityEngine.Vector3 GetHoleCreatePosition(global::DPData.UgSecretBase secretBase) {
            Vector3 offset = Vector3.zero;
            if (secretBase.direction == (byte)DIR.DIR_UP)
                offset = Vector3.forward;
            if (secretBase.direction == (byte)DIR.DIR_RIGHT)
                offset = Vector3.right;
            if (secretBase.direction == (byte)DIR.DIR_LEFT)
                offset = Vector3.left;
            return new Vector3(-secretBase.posX, 0.0f, secretBase.posY) + offset * 1.5f;
        }
		private float GetAngle(global::UnityEngine.Vector3 targetPos, global::DIR wallDIR) {
            Vector3 diff = targetPos - EntityManager.activeFieldPlayer.worldPosition;
            return Utils.Vector2ToAngle(new Vector2(diff.x, diff.z), 0.0f);
        }
		private float GetHoleCreateAngle(global::DPData.UgSecretBase secretBase) {
            switch ((DIR)secretBase.direction)
            {
                case DIR.DIR_UP:
                    return 180.0f;
                case DIR.DIR_RIGHT:
                    return 270.0f;
                case DIR.DIR_LEFT:
                    return 90.0f;
                default:
                    return 0.0f;
            }
        }
		public global::Dpr.UnderGround.UgFieldManager.SecretBaseModel CreateSecretBase_Immidiate(global::DPData.UgSecretBase secretBase, int stationIndex) {
            SecretBaseModel model;
            var existModel = SecretBases.Find(x => x.StationIndex == stationIndex);
            if (stationIndex == myStationIndex)
                existModel = SecretBases.Find(x => !x.isFriends);
            if (existModel != null)
                DeleteSecretBase(existModel, false);
            GameObject go = HoleInstantiate((DIR)secretBase.direction, new Vector3(-secretBase.posX, 0.0f, secretBase.posY));
            model = new SecretBaseModel(secretBase, stationIndex != myStationIndex, go, stationIndex);
            model.gridPos = new Vector2Int(secretBase.posX, secretBase.posY);
            SecretBases.Add(model);
            var digPoint = DigPoints.Find(x => x.gridPos == model.gridPos);
            if (digPoint != null)
            {
                digPoint.Destroy();
                DigPoints.Remove(digPoint);
            }
            return model;
        }
