		private void DeleteSecretBase(global::Dpr.UnderGround.UgFieldManager.SecretBaseModel model, bool immidiate) {
            if (model != null)
            {
                if (model.image != null)
                    Destroy(model.image.gameObject);
                if (model.go != null)
                {
                    if (immidiate)
                    {
                        Destroy(model.go);
                    }
                    else
                    {
                        SmartPoint.AssetAssistant.Sequencer.Start(Utils.LoadEffect(EffectFieldID.EF_F_CHARA_DRILL_CLOSE, data =>
                        {
                            if (model == null || model.go == null)
                                return;
                            SmartPoint.AssetAssistant.SingletonMonoBehaviour<EffectManager>.Instance.Play(data, model.go.transform.position, Quaternion.identity, null, null);
                            DG.Tweening.DOVirtual.DelayedCall(0.5f, () =>
                            {
                                if (model.go != null)
                                    Destroy(model.go);
                            }, true);
                        }));
                    }
                }
            }
            SecretBases.Remove(model);
        }
