		private bool CheckAroundWalls() {
            Vector3 position = EntityManager.activeFieldPlayer.transform.position;
            for (int i = 0; i < 8; i++)
                results[i] = Utils.CheckAttributeEnterable(position + eightDirect[i]);
            return results.All(x => x);
        }
		private global::UnityEngine.Vector3 GetAdjustPos() {
            Vector3 adjust = Vector3.zero;
            if (CheckResults(new int[] { 1, 2, 3 }))
                adjust += Vector3.back;
            if (CheckResults(new int[] { 3, 5, 8 }))
                adjust += Vector3.left;
            if (CheckResults(new int[] { 1, 4, 6 }))
                adjust += Vector3.right;
            if (CheckResults(new int[] { 6, 7, 8 }))
                adjust += Vector3.forward;
            if (adjust == Vector3.zero)
            {
                if (CheckResults(new int[] { 1 }))
                    adjust += Vector3.right + Vector3.back;
                else if (CheckResults(new int[] { 3 }))
                    adjust += Vector3.left + Vector3.back;
                else if (CheckResults(new int[] { 6 }))
                    adjust += Vector3.right + Vector3.forward;
                else if (CheckResults(new int[] { 8 }))
                    adjust += Vector3.left + Vector3.forward;
            }
            return adjust;
        }
		private bool CheckResults(params int[] index) {
            for (int i = 0; i < index.Length; i++)
            {
                if (!results[index[i] - 1])
                    return false;
            }
            return true;
        }
