		public void CreateSecretBaseRandom(int stationIndex) {
            if (SecretBases.FirstOrDefault(x => x.StationIndex == stationIndex) != null)
                return;
            var usablePosition = UgResManager.UgDrillUsablePositions.list.Find(x => x.zoneID == PlayerWork.zoneID);
            UgSecretBase secretBase = default;
            int posX = usablePosition.UseGrids[stationIndex].x;
            int posY = usablePosition.UseGrids[stationIndex].y;
            ZoneID zoneID = PlayerWork.zoneID;
            UgSecretBase myBase = PlayerWork.ugSaveData.ugRecord.myBase;
            DIR wallDir = Utils.GetWallDir(usablePosition.UseGrids[stationIndex]);
            if (!myBase.isNull && myBase.posX == (short)posX && myBase.posY == (short)posY)
            {
                posX = usablePosition.UseGrids[myStationIndex].x;
                posY = usablePosition.UseGrids[myStationIndex].y;
                wallDir = Utils.GetWallDir(usablePosition.UseGrids[myStationIndex]);
            }
            secretBase.zoneID = (short)zoneID;
            secretBase.posX = (short)posX;
            secretBase.posY = (short)posY;
            secretBase.direction = (byte)wallDir;
            CreateSecretBase_Immidiate(secretBase, stationIndex);
            OnCreateOtherSecretBase?.Invoke();
            miniMap.UpdateSecretBase(SecretBases);
        }
