		public void CreateOtherTonariHori(global::Dpr.NetworkUtils.NetDigData netDigData) {
            DeleteTargetTonarihori(netDigData.FromStationIndex);
            if (!CheckSamePosMySecretBase())
            {
                Create(netDigData.FromStationIndex, netDigData.data.digPos1);
                Create(netDigData.FromStationIndex, netDigData.data.digPos2);
            }
            if (miniMap == null)
                miniMap = FindObjectOfType<UgMiniMapComponent>();
            miniMap.UpdateDigPoint(digData);

            void CreateDigPoint(int stationIndex, DigPos p)
            {
                var model = new DigPointModel(p.GridX, p.GridY, myStationIndex)
                {
                    isFriends = true,
                    StationIndex = stationIndex,
                };
                DigPoints.Add(model);
                CreateDigPointGameObject(model);
                if (!PlayerWork.isDigFossil)
                    model.KiraKira(0.0f);
            }

            void Create(int stationIndex, DigPos p)
            {
                if (!p.IsNull)
                    CreateDigPoint(stationIndex, p);
            }

            bool CheckSamePosMySecretBase()
            {
                UgSecretBase myBase = PlayerWork.ugSaveData.ugRecord.myBase;
                if (myBase.isNull)
                    return false;
                return netDigData.data.MainPos.x == myBase.posX && netDigData.data.MainPos.y == myBase.posY;
            }
        }
