			private static readonly global::UnityEngine.Vector3[] directs = new global::UnityEngine.Vector3[] { new Vector3(0f, 0f, 1f), new Vector3(1f, 0f, 0f), new Vector3(-1f, 0f, 0f) };
			private static readonly global::UnityEngine.Vector2Int[] offsets = new global::UnityEngine.Vector2Int[] { new Vector2Int(0, 1), new Vector2Int(1, 0), new Vector2Int(-1, 0) };
			public DigPointModel(int x, int y, int staionIndex) {
				gridPos = new Vector2Int(x, y);
			}
			public global::UnityEngine.Vector2Int GetEffOffset() {
                for (int i = 0; i < directs.Length; i++)
                {
                    if (Utils.isEnterbleAttribute(cube.transform.position + directs[i], MoveType.FLY) == Utils.MoveTypeResult.OK)
                        return offsets[i];
                }
                return Vector2Int.zero;
            }
			public global::UnityEngine.Vector3 GetPosition() {
                return new Vector3(-gridPos.x, 0.0f, gridPos.y);
            }
			public void SetActive(bool isActive) {
                cube.SetActive(isActive);
                cube.GetComponent<FieldObjectEntity>().enabled = isActive;
            }
			public void Destroy() {
                EffectTra = null;
                if (cube != null)
                {
                    var entity = cube.GetComponent<FieldObjectEntity>();
                    if (entity != null)
                        EvScript.EvDataManager.Instanse.FieldObjectEntityRemove(entity);
                    UnityEngine.Object.Destroy(cube);
                }
                if (image != null)
                {
                    UnityEngine.Object.Destroy(image.gameObject);
                    image = null;
                }
                if (effIns != null)
                    effIns.Stop(0.0f, false);
                effIns = null;
            }
			public void KiraKira(float startDelay) {
                if (isKirakiraNow)
                    return;
                if (EffectTra.position == Vector3.zero)
                    return;
                isKirakiraNow = true;
                DG.Tweening.DOVirtual.DelayedCall(startDelay, () =>
                {
                    FieldManager.Instance.CallEffect(isFriends ? EffectFieldID.EF_SU_FUSSIL_POINT_FRIEND : EffectFieldID.EF_SU_FUSSIL_POINT, EffectTra, eff =>
                    {
                        if (UgFieldManager.Instance == null)
                        {
                            eff.Stop(0.0f, false);
                            return;
                        }
                        effIns = eff;
                        if (!isFriends)
                            eff.Stop(3.0f, false);
                    }, eff => isKirakiraNow = false);
                }, true);
            }
			static DigPointModel() { }
		}
		public abstract class MiniMapUIModelBase
		{
